use xiom.io;

use xiom.string;
fn get_setting(key: Str) -> Result[Option[Str], Str] {
  if key == "theme" { return Ok(Some("dark")); }
  if key == "font"  { return Ok(Some("mono")); }
  if key == "empty" { return Ok(None); }
  return Err("Setting not found: " + key);
}

fn parse_setting(key: Str) -> Result[Int, Str] {
  let setting = get_setting(key)?;
  return match setting {
    Some(text) => string.str_to_int(text),
    None => Err("Setting '" + key + "' has no value"),
  };
}

fn main() -> Int {
  match parse_setting("limit") {
    Ok(v) => io.println(string.int_to_str(v)),
    Err(e) => io.println(e.to_str()),
  };
  match parse_setting("empty") {
    Ok(v) => io.println(string.int_to_str(v)),
    Err(e) => io.println(e.to_str()),
  };
  match parse_setting("unknown") {
    Ok(v) => io.println(string.int_to_str(v)),
    Err(e) => io.println(e.to_str()),
  };
  return 0;
}
